@startuml

class Aircraft {
  + name : string
  + type : string
  + year_of_manufacture : int
  + next_inspection : date
}

class PassengerAircraft extends Aircraft {
  + number_of_seats : int
}

class SeatCategory {
  + designation : string
  + offers_entertainment_program : boolean
  + number_of_seats : int
}

class Flight {
  + flight_number : string
  + date : date
}

class Passenger {
  + name : string
  + passport_number : string
}

class Ticket {
  + ticket_number : string
  + price : float
  + upgrade_desired : boolean
}

class Airline {
  + name : string
}

class FlightAttendant {
  + name : string
  + date_of_employment : date
  + is_chief_steward_or_stewardess : boolean
}

class Pilot {
  + name : string
  + date_of_employment : date
  + license : string
}

class Airport {
  + name : string
  + address : string
  + number_of_runways : int
}

Aircraft "0..*" -- "0..1" Airline : belongs to
Aircraft "1" -- "*" Flight : performs
PassengerAircraft "1" *-- "1..*" SeatCategory : has
Flight "1" -- "*" Ticket : has
Passenger "1" -- "*" Ticket : holds
Ticket "*" -- "1" SeatCategory : for

Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives at
Aircraft "0..1" -- "1" Airport : home airport

Airline "1" -- "*" FlightAttendant : employs
Airline "1" -- "*" Pilot : employs

Flight "*" -- "1..*" FlightAttendant : staffed by
Flight -- "1" Pilot : Captain
Flight -- "1..2" Pilot : Co-pilot

@enduml

